.report table.authRefData { background-color: rgb(221, 238, 255); border: 2px solid rgb(47, 68, 151); font-size: 1em; position: absolute; }
.report table.authRefData a { display: block; font-weight: bold; }
.report table.authRefData p { margin-top: 0px; }
.report table.authRefData .hide { background-color: rgb(47, 68, 151); padding: 1px 3px 0px 0px; text-align: right; }
.report table.authRefData .hide a:hover { background-color: rgb(47, 68, 151); }
.report table.authRefData .body { height: 150px; overflow: auto; width: 400px; }
.report table.authRefData table { font-size: 1em; }
.pl a, .pl a:visited { color: black; text-decoration: none; }
.report { background-color: white; border: 2px solid rgb(170, 204, 255); clear: both; color: black; font: 8pt Helvetica, Arial, san-serif; margin-bottom: 2em; }
.report hr { border: 1px solid rgb(170, 204, 255); }
.report th { background-color: rgb(170, 204, 255); color: black; font-weight: bold; text-align: center; }
.report th.void { background-color: transparent; color: rgb(0, 0, 0); font: bold 10pt Helvetica, Arial, san-serif; text-align: left; }
.report .pl { text-align: left; vertical-align: top; width: 200px; white-space: normal; }
.report td.pl a.a { cursor: pointer; display: block; width: 200px; overflow: hidden; }
.report td.pl div.a { width: 200px; }
.report td.pl a:hover { background-color: rgb(255, 255, 204); }
.report tr.rh { background-color: rgb(170, 204, 255); color: black; font-weight: bold; }
.report .rc { background-color: rgb(240, 240, 240); }
.report .re, .report .reu { background-color: rgb(221, 238, 255); }
.report .reu td { border-bottom: 1px solid black; }
.report .ro, .report .rou { background-color: white; }
.report .rou td { border-bottom: 1px solid black; }
.report .rou table td, .report .reu table td { border-bottom: 0px solid black; }
.report .fn { white-space: nowrap; }
.report .num, .report .nump { text-align: right; white-space: nowrap; }
.report .nump { padding-left: 2em; }
.report .nump { padding: 0px 0.4em 0px 2em; }
.report .text { text-align: left; white-space: normal; }
.report .text .big { margin-bottom: 1em; width: 17em; }
.report .text .more { display: none; }
.report .text .note { font-style: italic; font-weight: bold; }
.report .text .small { width: 10em; }
.report sup { font-style: italic; }
.report .outerFootnotes { font-size: 1em; }

#headerTop, #headerBottom, #formDivPreviewer, #breadCrumbs, #help, #footer { display: none; }
